    /**
     * Tests getting all OrderItems.
     *
     * @return    Collection
     */
    public List<OrderItem> testGetAll() throws Throwable {
    LOGGER.info( "OrderItemTest:testGetAll() - Retrieving Collection of OrderItems:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all OrderItem : " );
    List<OrderItem> collection  = null;

    try {
        // call the static get method on the OrderItemService
        collection = service.getAllOrderItem();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            OrderItem currEntity  = null;
            Iterator<OrderItem> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getOrderItemId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

